library(EMC2);x<-EMC2:::restore_custom_kernel_pointers(EMC2:::restore_duplicates(readRDS('/tmp/lba_sampling_audit/snapshot.rds')),quiet=TRUE)
rec<-list()
for(j in seq_along(x)){obj<-readRDS(paste0('/tmp/lba_sampling_audit/proposals_chain',j,'.rds'));ch<-x[[j]];for(k in seq_along(obj$props)){bad_rows<-0;bad_subj<-0;t0_rows<-0;t0_subj<-0;for(s in seq_len(ch$n_subjects)){a<-matrix(obj$props[[k]][,s],1,dimnames=list(NULL,ch$par_names));pars<-EMC2:::get_pars_oo(a,ch$data[[s]],ch$model);b<-ch$model()$bound$minmax;nm<-intersect(colnames(b),colnames(pars));bad<-sweep(pars[,nm,drop=FALSE],2,b[1,nm],'<')|sweep(pars[,nm,drop=FALSE],2,b[2,nm],'>');ex<-ch$model()$bound$exception;for(en in intersect(names(ex),nm))bad[,en]<-bad[,en]&pars[,en]!=ex[en];ok<-rowSums(bad)==0;bad_rows<-bad_rows+sum(!ok);bad_subj<-bad_subj+any(!ok);rt<-ch$data[[s]]$rt;bad_t0<-is.finite(rt)&pars[,'t0']>=rt;t0_rows<-t0_rows+sum(bad_t0);t0_subj<-t0_subj+any(bad_t0)};rec[[length(rec)+1]]<-data.frame(chain=j,proposal=k,scale=obj$scales[k],bound_rows=bad_rows,bound_subjects=bad_subj,t0_rows=t0_rows,t0_subjects=t0_subj)}}
d<-do.call(rbind,rec);print(d,row.names=FALSE);write.csv(d,'/tmp/lba_sampling_audit/collapsed_bounds.csv',row.names=FALSE);print(aggregate(cbind(bound_subjects,t0_subjects)~scale,d,mean));cat('bound specification\n');str(x[[1]]$model()$bound)
